import { TodolistType } from '../../../../app/App';

const initState: TodolistType[] = [];

export const todolistsReducer = (state: TodolistType[] = initState, action: ActionType): TodolistType[] => {
    switch (action.type) {
        case 'REMOVE_TODOLIST': {
            const { todolistId } = action.payload;
            return state.filter((tl) => tl.id !== todolistId);
        }
        default:
            return state;
    }
};

export const removeTodolistAC = (payload: { todolistId: string }) => {
    return {
        type: 'REMOVE_TODOLIST',
        payload,
    } as const;
};

export type RemoveTodolistACType = ReturnType<typeof removeTodolistAC>;

export type ActionType = RemoveTodolistACType;
